package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import com.google.gson.*;
import java.nio.file.*;
final class CatalogueConditionsBrowserAcceptance {
 static void collect(CDPSession cdp,JsonArray reports){for(var entry:cdp.send("Profiler.takePreciseCoverage").getAsJsonArray("result")){var script=entry.getAsJsonObject();if(!script.get("url").getAsString().endsWith("/static/catalogue.js"))continue;var args=new JsonObject();args.add("scriptId",script.get("scriptId"));var report=new JsonObject();report.add("source",cdp.send("Debugger.getScriptSource",args).get("scriptSource"));report.add("functions",script.get("functions"));reports.add(report);}}
 static void run(BrowserTest h)throws Exception {
  String offering;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","ConditionalBrowserBuyer","password",WorkflowSupport.PASSWORD,"role","requester"));offering=Catalogue.save(db,actor,"",CatalogueAcceptance.offering("Conditional browser service",0,true)).get("offering_id").toString();CatalogueQuestions.save(db,actor,offering,map("revision",1,"questions",CatalogueConditionsAcceptance.questions()));String group=Service.create(db,"sys_user_group",map("short_description","Conditional fulfilment team"),"admin").get("sys_id").toString();CatalogueRouting.save(db,actor,offering,map("group_id",group,"revision",2));db.connection.commit();}
  var reports=new JsonArray();try(var p=Playwright.create();var browser=p.chromium().launch();var administrator=browser.newContext();var requester=browser.newContext();var noScript=browser.newContext(new Browser.NewContextOptions().setJavaScriptEnabled(false))){
   var admin=administrator.newPage();h.login(admin,"admin");var adminCdp=ThemeBrowserAcceptance.instrument(administrator,admin);admin.navigate(h.base()+"/admin/catalogue/"+offering+"/questions?question=reason");assertThat(admin.getByLabel("Show when earlier question key")).hasValue("needed");assertThat(admin.getByLabel("Matches answer")).hasValue("true");admin.getByLabel("Question label",new Page.GetByLabelOptions().setExact(true)).fill("Question reason");ReleaseBrowserAcceptance.accessible(admin);admin.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/catalogue-conditions-editor-light.png")).setFullPage(true));collect(adminCdp,reports);ServiceOutagesBrowserAcceptance.click(admin,"Save question");assertThat(admin.locator("main")).containsText("Current questions");
   var page=requester.newPage();FulfilmentBrowserAcceptance.login(h,page,"ConditionalBrowserBuyer");var cdp=ThemeBrowserAcceptance.instrument(requester,page);page.navigate(h.base()+"/catalogue/"+offering);var script=requester.request().get(h.base()+"/static/catalogue.js");assertEquals(200,script.status());assertTrue(script.headers().get("content-type").startsWith("text/javascript"));assertEquals(Files.readString(Path.of("src/main/resources/static/catalogue.js")),script.text());assertThat(page.locator("#answer-reason")).isHidden();assertThat(page.locator("#answer-needed")).isDisabled();page.getByLabel("Question kind (required)").selectOption("Special");assertThat(page.locator("#answer-needed")).isVisible();assertEquals(true,page.locator("#answer-needed").evaluate("e=>e.required"));assertThat(page.locator("#answer-reason")).isHidden();page.getByLabel("Question needed (required)").selectOption("false");assertThat(page.locator("#answer-reason")).isHidden();page.getByLabel("Question needed (required)").selectOption("true");page.getByLabel("Question reason (required)").fill("Project justification <script>");page.getByLabel("Question amount (optional)").fill("3");page.getByLabel("Question start (optional)").fill("2026-11-20");page.getByLabel("Question comment (optional)").fill("Visible optional comment");assertEquals(true,page.locator("#answer-reason").evaluate("e=>e.required"));assertEquals(false,page.locator("#answer-amount").evaluate("e=>e.required"));ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/catalogue-conditions-visible-dark.png")).setFullPage(true));page.getByLabel("Question kind (required)").selectOption("Standard");assertThat(page.locator("#answer-reason")).isHidden();assertThat(page.locator("#answer-reason")).hasValue("");assertThat(page.locator("#answer-needed")).hasValue("");assertEquals(false,page.locator("#answer-reason").evaluate("e=>e.required"));ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/catalogue-conditions-cleared-dark.png")).setFullPage(true));collect(cdp,reports);ServiceOutagesBrowserAcceptance.click(page,"Submit service request");assertThat(page.locator("main")).containsText("Question kind");assertThat(page.locator("main")).not().containsText("Question reason");String request=new java.net.URI(page.url()).getPath().replace("/record/sc_request/","");try(var db=h.store.open()){assertEquals("queued",db.one("SELECT state FROM os_fulfilment WHERE request_id=?",request).get("state"));}
   var fallback=noScript.newPage();FulfilmentBrowserAcceptance.login(h,fallback,"ConditionalBrowserBuyer");fallback.navigate(h.base()+"/catalogue/"+offering);assertThat(fallback.locator("#answer-reason")).isVisible();assertEquals(false,fallback.locator("#answer-reason").evaluate("e=>e.required"));fallback.getByLabel("Question kind (required)").selectOption("Standard");ServiceOutagesBrowserAcceptance.click(fallback,"Submit service request");assertThat(fallback.locator("main")).not().containsText("Question reason");
   try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.store.environment)){
    provider.settings.put("AI_CATALOGUE_ENABLED","true");provider.answer.set("Suggested conditional details");page.navigate(h.base()+"/catalogue/"+offering+"/assistant");page.getByLabel("Your description").fill("Prepare a special request");ServiceOutagesBrowserAcceptance.click(page,"Preview what will be sent");page.getByLabel("Send this description and offering to the configured provider").check();ServiceOutagesBrowserAcceptance.click(page,"Generate an editable draft");assertThat(page.locator("#assist-answer-reason")).isHidden();page.getByLabel("Question kind (required)").selectOption("Special");page.getByLabel("Question needed (required)").selectOption("true");page.getByLabel("Question reason (required)").fill("Assisted conditional reason");collect(cdp,reports);ServiceOutagesBrowserAcceptance.click(page,"Review this service request");assertThat(page.locator("main")).containsText("Assisted conditional reason");ServiceOutagesBrowserAcceptance.click(page,"Edit reviewed request");assertThat(page.locator("#assist-answer-reason")).isVisible();assertThat(page.locator("#assist-answer-reason")).hasValue("Assisted conditional reason");page.getByLabel("Question kind (required)").selectOption("Standard");assertThat(page.locator("#assist-answer-reason")).hasValue("");collect(cdp,reports);ServiceOutagesBrowserAcceptance.click(page,"Review this service request");assertThat(page.locator("main")).not().containsText("Assisted conditional reason");page.getByLabel("Create this reviewed service request").check();ServiceOutagesBrowserAcceptance.click(page,"Submit reviewed request");assertThat(page.locator("main")).containsText("Suggested conditional details");assertThat(page.locator("main")).not().containsText("Question reason");assertEquals(1,provider.calls.get());
   }
  }
  assertFalse(reports.isEmpty());Files.writeString(Path.of("target/catalogue-browser-v8.json"),reports.toString());
 }
}
